      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {F : Type u_2} [inst_1 : NormedAddCommGroup F]\n  [inst_2 : NormedSpace 𝕜 F] {n : ℕ} {x : 𝕜} {s : Set 𝕜},\n  x ∈ s →\n    UniqueDiffOn 𝕜 s →\n      ∀ {𝕜' : Type u_4} [inst_3 : NontriviallyNormedField 𝕜'] [inst_4 : NormedAlgebra 𝕜 𝕜'] [inst_5 : NormedSpace 𝕜' F]\n        [IsScalarTower 𝕜 𝕜' F] {f : 𝕜 → 𝕜'} {g : 𝕜 → F},\n        ContDiffWithinAt 𝕜 (↑n) f s x →\n          ContDiffWithinAt 𝕜 (↑n) g s x →\n            iteratedDerivWithin n (f • g) s x =\n..."
    },
    {
      "name": "iteratedDeriv_fun_mul",
      "module_name": "Mathlib.Analysis.Calculus.IteratedDeriv.Lemmas",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {n : ℕ} {x : 𝕜} {𝕜' : Type u_4}\n  [inst_1 : NontriviallyNormedField 𝕜'] [inst_2 : NormedAlgebra 𝕜 𝕜'] {f g : 𝕜 → 𝕜'},\n  ContDiffAt 𝕜 (↑n) f x →\n    ContDiffAt 𝕜 (↑n) g x →\n      iteratedDeriv n (fun x => f x * g x) x =\n        ∑ i ∈ Finset.range (n + 1), ↑(n.choose i) * iteratedDeriv i f x * iteratedDeriv (n - i) g x"
    },
